+        final long timeoutMs = timeout.toMillis();
+        boolean interrupted = false;
+        try {
+            while (true) {
+                final long remainingMs = timeoutMs - TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startNs);
+                if (remainingMs <= 0) {
